const nodes = [...document.querySelectorAll('[data-t]')];
const altNodes = [...document.querySelectorAll('[data-alt]')];
const english = Object.fromEntries(nodes.map(node => [node.dataset.t, node.textContent]));
for (const node of altNodes) english[node.dataset.alt] = node.alt;
Object.assign(english,{studioTitle:'Independent.\nIntentional.',copied:'Link copied.',copyFailed:'Copy the link from your address bar.',count:'projects shown'});
const locale = document.querySelector('#locale');
const filters = [...document.querySelectorAll('[data-filter]')];
const projects = [...document.querySelectorAll('[data-category]')];
const filterStatus = document.querySelector('#filter-status');
const shareStatus = document.querySelector('#share-status');
const params = new URLSearchParams(location.search);
let language = ['en','ko','ja','zh-CN'].includes(params.get('lang')) ? params.get('lang') : 'en';
let category = 'all';
function strings(){return language === 'en' ? english : translations[language];}
function applyFilter(next){category=next;for(const button of filters)button.setAttribute('aria-pressed',String(button.dataset.filter===next));for(const project of projects)project.hidden=next!=='all'&&project.dataset.category!==next;filterStatus.textContent=`${projects.filter(p=>!p.hidden).length} ${strings().count}`;}
function applyLanguage(next){language=next;document.documentElement.lang=next;locale.value=next;const t=strings();for(const node of nodes)node.textContent=t[node.dataset.t]??english[node.dataset.t];for(const node of altNodes)node.alt=t[node.dataset.alt]??english[node.dataset.alt];applyFilter(category);shareStatus.textContent='';const url=new URL(location.href);if(next==='en')url.searchParams.delete('lang');else url.searchParams.set('lang',next);history.replaceState(null,'',url);}
locale.addEventListener('change',()=>applyLanguage(locale.value));
filters.forEach(button=>button.addEventListener('click',()=>applyFilter(button.dataset.filter)));
document.querySelector('#share').addEventListener('click',async()=>{try{const url=new URL(location.href);url.hash='';await navigator.clipboard.writeText(url.href);shareStatus.textContent=strings().copied;}catch{shareStatus.textContent=strings().copyFailed;}});
document.querySelector('#copyright-year').textContent = String(new Date().getFullYear());
applyLanguage(language);
